import json

try:
    from StringIO import StringIO
except ImportError:
    from io import StringIO
from six import string_types
import re
from ta_tshark_json_parser.json_packet_finder import JasonPacketFinder
from ta_tshark_json_parser.logger_config import configure_raw_message_logger, configure_logger


class TsharkFieldParser(object):
    """
    Class used to parse fields returned from tshark output with option -E fields.
    Tshark output with specified column could be determined with ColumnSourceDescription class.
    Default ColumnSourceDescription provided above consists of columns: gtp_teidand corresponding tshark command
     must be invoked with parameters:
      ./tshark -T json
    """
    JSON_MANDATORY_SUBS = [
                            (':(\s*)null', ':\g<1>\"null\"')
                            ]
    JSON_DUPLICATED_KEYS_HANDLERS = [None, 'as_list', 'add_suffix_number']

    def __init__(self, layer=None, stop_condition=None,
                 source_output_substitutes=None, duplicated_keys_handler=None,
                 logger_suffix=""):
        """
        :param stop_condition:
        :param layer: subclass of ColumnSourceDescription class object
        :param source_output_substitues: list of tuples, default substitute is applied to hex value in tshark output,
        changes 00:11 to 0011
        """
        self.logger = configure_logger('ta_tshark_json_parser.field_parser.{}'.format(logger_suffix))
        assert duplicated_keys_handler in TsharkFieldParser.JSON_DUPLICATED_KEYS_HANDLERS, \
            'Wrong duplicates handler, possible: {}'.format(TsharkFieldParser.JSON_DUPLICATED_KEYS_HANDLERS)
        self.duplicated_keys_handler = duplicated_keys_handler
        self.logger.info('Staring parser for layer:{}'.format(layer) if layer is not None else
                         "Starting parser for all layers")
        self.layer = layer
        self.source_logger = configure_raw_message_logger('ta_tshark_json_parser.field_parser.raw_source.{}'
                                                          .format(logger_suffix))
        self.source_output_substitutes = source_output_substitutes
        self._default_stop_condition = lambda: 9999
        self.stop_condition = stop_condition if stop_condition is not None else self._default_stop_condition

    def get_data_record_list(self, file_or_string):
        """
        Returns list of data records/.
        :param file_or_string: must be a finite source e.g. file or string, not a process!.
        :return:
        """
        return [msg for msg in self.iter_data_records(file_or_string)]

    def iter_data_records(self, source):
        """
        Generator that return data record implemented as namedtuples in ColumnSourceDescription class.
        :param source: either string or file-like objects implementing read(size)
        :return: namedtuple
        """
        for single_packet in self.iter_line_records(source):
            single_packet = self.convert_nonunique_protocols_in_single_packet(single_packet)
            record = self.convert_line_to_data_record(single_packet)
            self.logger.debug(record)
            yield record

    def convert_nonunique_protocols_in_single_packet(self, packet):
        """

        :param packet:
        :return:
        """
        to_convert_raw_string = self.layer
        if to_convert_raw_string is not None:
            to_convert_raw_string = str(to_convert_raw_string)
            to_convert_with_braces = "\"" + str(to_convert_raw_string) + "\""
            to_sub_ppatern = "\"{} {}\""
            to_convert_len = len(to_convert_with_braces)
            layer_occur_count = packet.count(to_convert_with_braces)
            print('Found {} occurences of : {}'.format(layer_occur_count, to_convert_with_braces))
            if layer_occur_count > 1:
                pos = 0
                for i in range(0, layer_occur_count):
                    pos = packet.find(to_convert_with_braces, pos)
                    to_sub = to_sub_ppatern.format(to_convert_raw_string, i)
                    packet = packet[:pos] + to_sub + packet[pos + to_convert_len:]
                    self.logger.info('Changing occurrence of: {} to: {}'.format(to_convert_with_braces, to_sub))
                    pos += len(to_sub)
        return packet

    def iter_line_records(self, hex_source):
        """
        Generator that returns single records (single line with all required columns declared in tshark.
        :param hex_source:
        :return: single tshark line with all declared columns
        """
        file_like_data_source = self.unify_read_api(hex_source)
        remaining = ""
        for chunk in self.iter_chunk(file_like_data_source):
            self.source_logger.debug(chunk)
            remaining = "".join([remaining, chunk])
            end = 0

            for (packet, end) in JasonPacketFinder.find_packet(remaining):
                yield packet
            remaining = remaining[end:]

    def iter_chunk(self, data_source, chunk_size=4096*128):
        """
        Gets chunk of data source and returns them. Empty lines are omit, 'None' chunk brakes the loop
        :param data_source:
        :param chunk_size:
        :return:
        """
        while self.stop_condition():
            chunk = data_source.read(chunk_size)
            if chunk is None:
                break
            if chunk == "":
                continue
            # print len(chunk)
            yield self._apply_substitutions_for_output(chunk)

    def _apply_substitutions_for_output(self, chunk):
        # for (sub_from, sub_to) in self.source_output_substitutes:
        #     chunk = re.sub(sub_from, sub_to, chunk)
        return chunk

    def unify_read_api(self, file_or_string_data_source):
        """
        Reading either from string or from file-like objects implementing read(size). Implemented to support some post-processing of log file.
        :param file_or_string_data_source:
        :return:
        """
        if isinstance(file_or_string_data_source, string_types):
            string_data_source = file_or_string_data_source
            file_like_data_source = StringIO(string_data_source)
        else:
            file_like_data_source = file_or_string_data_source
        assert hasattr(file_like_data_source, "read")
        return file_like_data_source

    def _on_duplicate_keys(self):
        if self.duplicated_keys_handler == 'as_list':
            return self.array_on_duplicate_keys
        elif self.duplicated_keys_handler == 'add_suffix_number':
            return self.num_suffix_on_duplicate_keys

    def array_on_duplicate_keys(self, ordered_pairs):
        """Convert duplicate keys to arrays."""
        d = {}
        for k, v in ordered_pairs:
            if k in d:
                if type(d[k]) is list:
                    d[k].append(v)
                else:
                    d[k] = [d[k], v]
            else:
                d[k] = v
        return d

    def num_suffix_on_duplicate_keys(self, ordered_pairs):
        """Convert duplicate keys to 'Key N+1' keys."""
        d = {}
        occurrences = {}
        for k, v in ordered_pairs:
            if k in d:
                occurrences[k] += 1
                d["{} {}".format(k, occurrences[k])] = v
            else:
                occurrences[k] = 1
                d[k] = v
        return d

    def _decode_by_json(self, line):
        object_pairs_hook = self._on_duplicate_keys()
        return json.loads(line, object_pairs_hook=object_pairs_hook)

    def _decode_by_evaluation(self, line):
        return eval(line)

    def convert_line_to_data_record(self, hex_line):
        """
        Based on single tshark line with all columns and supplied ColumnSourceDescription, returns single data record (namedtuple).
        In data record all columns declared in ColumnSourceDescription are available.
        :param hex_line: e.g.
        :return:
        """
        _line = hex_line
        for sub in TsharkFieldParser.JSON_MANDATORY_SUBS:
            _line = re.sub(sub[0], sub[1], _line)
        if self.duplicated_keys_handler is None:
            return self._decode_by_evaluation(_line)
        else:
            return self._decode_by_json(_line)
